public class InnerJobTemplateParametricMonitoringConfigurationFactory(Action<Humidifier.EMRContainers.JobTemplateTypes.ParametricMonitoringConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.EMRContainers.JobTemplateTypes.ParametricMonitoringConfiguration>
{

    internal InnerJobTemplateParametricS3MonitoringConfigurationFactory S3MonitoringConfigurationFactory { get; set; }

    internal InnerJobTemplateParametricCloudWatchMonitoringConfigurationFactory CloudWatchMonitoringConfigurationFactory { get; set; }

    protected override Humidifier.EMRContainers.JobTemplateTypes.ParametricMonitoringConfiguration Create()
    {
        var parametricMonitoringConfigurationResult = CreateParametricMonitoringConfiguration();
        factoryAction?.Invoke(parametricMonitoringConfigurationResult);

        return parametricMonitoringConfigurationResult;
    }

    private Humidifier.EMRContainers.JobTemplateTypes.ParametricMonitoringConfiguration CreateParametricMonitoringConfiguration()
    {
        var parametricMonitoringConfigurationResult = new Humidifier.EMRContainers.JobTemplateTypes.ParametricMonitoringConfiguration();

        return parametricMonitoringConfigurationResult;
    }
    public override void CreateChildren(Humidifier.EMRContainers.JobTemplateTypes.ParametricMonitoringConfiguration result)
    {
        base.CreateChildren(result);

        result.S3MonitoringConfiguration ??= S3MonitoringConfigurationFactory?.Build();
        result.CloudWatchMonitoringConfiguration ??= CloudWatchMonitoringConfigurationFactory?.Build();
    }

} // End Of Class

